/**
 * The finite code/type rewrite ({@code FINITE_CODE_TYPE_VALUES}) replaces a value-equality FILTER over the code
 * variable by a term-identity JOIN with a VALUES domain. Like the finite-filter rule it must therefore decline unless
 * every code constant is term-identity safe (an IRI, a blank node, an xsd:string or a language-tagged literal): a
 * stored {@code 1.0} value-equals the constant {@code 1} in the filter but is never term-equal to it in the join.
 */
class PackedCodeTypeTermIdentityTest {

	private static final String CODE_TYPE_QUERY = """
			SELECT (COUNT(DISTINCT ?e) AS ?n) WHERE {
			  { ?e a :T1 . ?e :code ?c . VALUES ?t { 1 2 } FILTER(?c = ?t || ?c = 3) }
			  UNION
			  { ?e a :T2 . ?e :code ?c . VALUES ?t { 1 2 } FILTER(?c = ?t || ?c = 3) }
			}
			""";

	private static Model numericCodeData() {
		Model data = model();
		data.add(iri("e1"), RDF.TYPE, iri("T1"));
		add(data, "e1", "code", VF.createLiteral("1.0", CoreDatatype.XSD.DECIMAL));
		data.add(iri("e2"), RDF.TYPE, iri("T2"));
		add(data, "e2", "code", VF.createLiteral("2", CoreDatatype.XSD.INTEGER));
		data.add(iri("e3"), RDF.TYPE, iri("T1"));
		add(data, "e3", "code", VF.createLiteral("5", CoreDatatype.XSD.INTEGER));
		return data;
	}

	// ------------------------------------------------------------------ reviewer's shapes

	@Test
	void codeTypeRewriteWithoutScopeFlagsKeepsValueEqualCodes() {
		Model data = numericCodeData();
		TupleExpr original = parse(CODE_TYPE_QUERY);
		clearNonProjectionScopeFlags(original);
		List<String> reference = evaluate(data, original);
		assertEquals(List.of("n=\"2\"^^<http://www.w3.org/2001/XMLSchema#integer>"), reference,
				"reference oracle disagrees with hand-computed bag");
		long generated = generatedRuleMask(PackedQueryCodec.encodeForPlanning(original.clone(), null));
		TupleExpr selected = PackedCascadesPlanner
				.optimize(original.clone(), OptimizationGoal.root(original, null), SUBJECT_LOOKUP_COSTS)
				.selectedPlan();
		assertEquals(reference, evaluate(data, selected),
				"selected plan changed the count (generated=0x" + Long.toHexString(generated) + ")\n" + selected);
		assertEquals(0L, generated & PackedRuleProofs.FINITE_CODE_TYPE_VALUES,
				"numeric codes are not term-identity safe, so the code/type rewrite must be declined");
	}

	@Test
	void codeTypeRewriteKeepsValueEqualCodesWithParserScopeFlags() {
		assertPackedPlanPreservesResults(numericCodeData(), CODE_TYPE_QUERY, SUBJECT_LOOKUP_COSTS, null,
				List.of("n=\"2\"^^<http://www.w3.org/2001/XMLSchema#integer>"));
	}

	// ------------------------------------------------------------------ rule-mask scan by code datatype

	@Test
	void stringCodesKeepTheRewrite() {
		assertTrue(generatesCodeTypeRewrite(VF.createLiteral("DX-200"), VF.createLiteral("DX-201"),
				VF.createLiteral("DX-202")), "xsd:string codes have one term per value: the rewrite is sound");
	}

	@Test
	void iriCodesKeepTheRewrite() {
		assertTrue(generatesCodeTypeRewrite(iri("c1"), iri("c2"), iri("c3")));
	}

	@Test
	void languageTaggedCodesKeepTheRewrite() {
		assertTrue(generatesCodeTypeRewrite(VF.createLiteral("a", "en"), VF.createLiteral("b", "en"),
				VF.createLiteral("c", "en")));
	}

	@Test
	void integerCodesDeclineTheRewrite() {
		assertFalse(generatesCodeTypeRewrite(VF.createLiteral("1", CoreDatatype.XSD.INTEGER),
				VF.createLiteral("2", CoreDatatype.XSD.INTEGER), VF.createLiteral("3", CoreDatatype.XSD.INTEGER)));
	}

	@Test
	void decimalCodesDeclineTheRewrite() {
		assertFalse(generatesCodeTypeRewrite(VF.createLiteral("1.0", CoreDatatype.XSD.DECIMAL),
				VF.createLiteral("2.0", CoreDatatype.XSD.DECIMAL), VF.createLiteral("3.0", CoreDatatype.XSD.DECIMAL)));
	}

	@Test
	void booleanAndDateCodesDeclineTheRewrite() {
		assertFalse(generatesCodeTypeRewrite(VF.createLiteral(true), VF.createLiteral(false),
				VF.createLiteral("1", CoreDatatype.XSD.BOOLEAN)));
		assertFalse(generatesCodeTypeRewrite(VF.createLiteral("2020-01-01", CoreDatatype.XSD.DATE),
				VF.createLiteral("2020-01-02", CoreDatatype.XSD.DATE),
				VF.createLiteral("2020-01-03", CoreDatatype.XSD.DATE)));
	}

	@Test
	void mixedCodesDeclineTheRewrite() {
		assertFalse(generatesCodeTypeRewrite(VF.createLiteral("DX-200"), VF.createLiteral("DX-201"),
				VF.createLiteral("3", CoreDatatype.XSD.INTEGER)), "one numeric literal among string codes suffices");
		assertFalse(generatesCodeTypeRewrite(VF.createLiteral("1", CoreDatatype.XSD.INTEGER),
				VF.createLiteral("DX-201"), VF.createLiteral("DX-202")), "the VALUES rows are checked too");
	}

	// ------------------------------------------------------------------ helpers

	private static boolean generatesCodeTypeRewrite(Value first, Value second, Value third) {
		List<Value> codes = List.of(first, second, third);
		TupleExpr input = new Union(codeTypeBranch("urn:t:T1", codes), codeTypeBranch("urn:t:T2", codes));
		Group source = new Group(input, List.of(), List.of(new GroupElem("count", new Count(Var.of("entity"), true))));
		return (generatedRuleMask(PackedQueryCodec.encodeForPlanning(source))
				& PackedRuleProofs.FINITE_CODE_TYPE_VALUES) != 0L;
	}

	/**
	 * {@code { ?entity a <type> . ?entity :code ?code . VALUES ?target {c0 c1} FILTER(?code = ?target || ?code = c2) }}
	 */
	private static TupleExpr codeTypeBranch(String type, List<Value> codes) {
		BindingSetAssignment targets = new BindingSetAssignment();
		targets.setBindingNames(Set.of("target"));
		MapBindingSet firstRow = new MapBindingSet();
		firstRow.setBinding("target", codes.get(0));
		MapBindingSet secondRow = new MapBindingSet();
		secondRow.setBinding("target", codes.get(1));
		targets.setBindingSets(List.of(firstRow, secondRow));
		StatementPattern typePattern = new StatementPattern(Var.of("entity"), Var.of("rdfType", RDF.TYPE),
				Var.of("typeValue", VF.createIRI(type)));
		StatementPattern codePattern = new StatementPattern(Var.of("entity"), Var.of("codePredicate", iri("code")),
				Var.of("code"));
		Join patterns = new Join(typePattern, codePattern);
		patterns.setVariableScopeChange(true);
		Or condition = new Or(new Compare(Var.of("code"), Var.of("target"), Compare.CompareOp.EQ),
				new Compare(Var.of("code"), new ValueConstant(codes.get(2)), Compare.CompareOp.EQ));
		return new Filter(new Join(targets, patterns), condition);
	}

	private static void clearNonProjectionScopeFlags(TupleExpr expression) {
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof VariableScopeChange scope && !(node instanceof Projection)) {
					scope.setVariableScopeChange(false);
				}
				super.meetNode(node);
			}
		});
	}
}
